/* ============================================================================
   Mantenimiento — copiar a PRODUCCIÓN (AdelantePRO) los EQUIPOS y sus
   CHECKLISTS DIARIOS que están cargados en AdelanteSBX.

   Foto de SBX del 2026-10-20: 52 equipos (46 con checklist) y 496 actividades.
   Generado por script a partir de mant.Equipos y mant.ChecklistDiarioItems de SBX.

   Qué copia:
   - mant.Equipos: todos los datos del equipo, con el MISMO id (GUID) que en SBX.
   - mant.ChecklistDiarioItems: las actividades de cada equipo (orden 0..n-1).

   Qué NO copia (a propósito):
   - Manuales PDF y fotos (viven en mant.Archivos, ~35 MB): se vuelven a subir
     desde la app. Por eso fotoId y manuales quedan en NULL.
   - Inspecciones, OTs, repuestos, planes, lecturas: son datos de prueba de SBX.

   Seguridad:
   - Solo INSERTA lo que falta. Nunca actualiza ni borra nada de PRO.
   - Equipo: se salta si en PRO ya existe uno con el mismo id o el mismo código.
   - Checklist: solo se carga en equipos de PRO que todavía NO tienen ninguna
     actividad (se busca el equipo por código), así no se duplica nada.
   - Todo en UNA transacción y en un solo lote (sin GO): entra completo o nada.
   - Se puede correr más de una vez: la segunda vez no inserta nada.
   ============================================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
BEGIN TRANSACTION;

DECLARE @Equipos TABLE (
    id UNIQUEIDENTIFIER PRIMARY KEY,
    codigo NVARCHAR(50),
    nombre NVARCHAR(200),
    tipo NVARCHAR(50),
    marca NVARCHAR(100),
    modelo NVARCHAR(100),
    anio INT,
    numeroSerie NVARCHAR(100),
    horometroActual DECIMAL(12,1),
    estado NVARCHAR(30),
    ubicacion NVARCHAR(150),
    intervaloHorasPreventivo DECIMAL(12,1),
    notas NVARCHAR(MAX),
    creadoEn DATETIME2,
    placa NVARCHAR(30),
    revisionTecnica NVARCHAR(50),
    fechaIngreso NVARCHAR(50),
    kilometraje DECIMAL(12,1),
    combustible NVARCHAR(30),
    filtroAceite NVARCHAR(60),
    filtroDiesel NVARCHAR(60),
    filtroAireAcondicionado NVARCHAR(60),
    llantasDelanteras NVARCHAR(60),
    llantasTraseras NVARCHAR(60),
    cilindraje NVARCHAR(30),
    intervaloKilometrajePreventivo DECIMAL(12,1),
    ultimaFechaMantenimiento NVARCHAR(50),
    proximaFechaMantenimiento NVARCHAR(50)
);


DECLARE @Items TABLE (
    id UNIQUEIDENTIFIER PRIMARY KEY,
    equipoIdSbx UNIQUEIDENTIFIER NOT NULL,
    orden INT NOT NULL,
    titulo NVARCHAR(200) NOT NULL,
    detalle NVARCHAR(500) NULL,
    creadoEn DATETIME2 NOT NULL
);


-- 1) Equipos que faltan (ni el id ni el código existen en PRO).
SELECT e.id, e.codigo, e.nombre, e.tipo, e.marca, e.modelo, e.anio, e.numeroSerie, e.horometroActual, e.estado, e.ubicacion, e.intervaloHorasPreventivo, e.notas, e.creadoEn, e.placa, e.revisionTecnica, e.fechaIngreso, e.kilometraje, e.combustible, e.filtroAceite, e.filtroDiesel, e.filtroAireAcondicionado, e.llantasDelanteras, e.llantasTraseras, e.cilindraje, e.intervaloKilometrajePreventivo, e.ultimaFechaMantenimiento, e.proximaFechaMantenimiento, NULL, NULL
FROM @Equipos e
WHERE NOT EXISTS (SELECT 1 FROM mant.Equipos x WHERE x.id = e.id OR x.codigo = e.codigo);

-- 2) Checklist solo para equipos de PRO que aún no tienen ninguna actividad.
--    El equipo se busca por CÓDIGO (por si en PRO ya existía con otro id).
SELECT i.id, destino.id, i.orden, i.titulo, i.detalle, i.creadoEn
FROM @Items i
JOIN @Equipos origen ON origen.id = i.equipoIdSbx
JOIN mant.Equipos destino ON destino.codigo = origen.codigo
WHERE NOT EXISTS (SELECT 1 FROM mant.ChecklistDiarioItems c WHERE c.equipoId = destino.id)
  AND NOT EXISTS (SELECT 1 FROM mant.ChecklistDiarioItems c WHERE c.id = i.id);

COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
